function kthBusiest(scores: number[], k: number): number {
  const heap: number[] = [];
  const up = (i: number) => { while (i && heap[(i - 1) >> 1] > heap[i]) { [heap[i], heap[(i - 1) >> 1]] = [heap[(i - 1) >> 1], heap[i]]; i = (i - 1) >> 1; } };
  const down = (i: number) => { for (;;) { let m = i; const l = 2 * i + 1, r = l + 1; if (l < heap.length && heap[l] < heap[m]) m = l; if (r < heap.length && heap[r] < heap[m]) m = r; if (m === i) return; [heap[i], heap[m]] = [heap[m], heap[i]]; i = m; } };
  for (const s of scores) {
    if (heap.length < k) { heap.push(s); up(heap.length - 1); }
    else if (s > heap[0]) { heap[0] = s; down(0); }
  }
  return heap[0];
}
